INSERT INTO feature VALUES('paper-watch','workflow','A weekly paper watch',NULL,'implemented','ordinary',NULL,'`refs:watch` asks OpenAlex for the works published since its last run that cite a work the tree cites, follow one by its own authors on its topic, come from a library author, or appear in a library journal or conference on a term of the term map, and comments them by seed on one review issue; a work the state already reported, or the vault ledger''s `paper` table settles, never reappears. A library entry holds a work in any version, by a DOI, arXiv or HAL identifier any of its locations shares, or by its title and first author; a version OpenAlex keeps apart is reported once as a version of its entry, and every row links its arXiv version, else its HAL one, before its DOI.',NULL,'.config/references/watch.json',NULL,NULL);
